export default '/**\n * Stackra file contract:\n * Purpose: the "matching" demo of the native BulkActionBar: a selected page offers every matching row the server counts.\n * Boundary: a demo with no props, @stackra/ui and local state only; the same file is the preview and the code shown.\n * Runtime: react-native\n * Governing contract: showcase redesign spec (2026-10-27) section 4 (demo contract); ADR 0310 (decision 6).\n */\nimport type { ResourceAction } from "@stackra/ui/contracts";\nimport { BulkActionBar, useCatalogueText } from "@stackra/ui/native";\nimport { useState } from "react";\n\nimport { Icons } from "#src/constants/icons.constant";\nimport { MESSAGES } from "#src/constants/messages.constant";\nimport { BULK_ACTION_BAR_DEMO_KEYS } from "#src/demos/free/bulk-action-bar/bulk-action-bar-demo-keys.constant";\n\n/** The demo\'s keys. */\nconst A = BULK_ACTION_BAR_DEMO_KEYS.demo_free.bulk_action_bar.actions;\nconst K = BULK_ACTION_BAR_DEMO_KEYS.demo_free.bulk_action_bar.matching;\n\n/** The total the pretend server counts, and how many rows a page shows. */\nconst TOTAL = 245;\nconst PAGE = 20;\n\n/** Every row on screen selected; choosing "all matching" makes the total the count. */\nexport default function Matching() {\n  const [isAll, setIsAll] = useState(false);\n  const t = useCatalogueText(MESSAGES.en);\n  // Actions that only have to be there: their handlers do nothing.\n  const actions: readonly ResourceAction[] = [\n    { id: "send", label: t(A.send), icon: Icons.SendHorizontal, onPress: () => undefined },\n    { id: "archive", label: t(A.archive), icon: Icons.Archive, onPress: () => undefined },\n    { id: "download", label: t(A.download), icon: Icons.Download, onPress: () => undefined },\n    {\n      id: "delete",\n      label: t(A.delete),\n      icon: Icons.Trash,\n      tone: "danger",\n      onPress: () => undefined,\n    },\n  ];\n  return (\n    <BulkActionBar\n      label={t(K.label)}\n      selectedCount={PAGE}\n      isPageSelected\n      totalCount={TOTAL}\n      isAllMatchingSelected={isAll}\n      onAllMatchingSelectedChange={setIsAll}\n      actions={actions.slice(0, 2)}\n      onClearSelection={() => setIsAll(false)}\n    />\n  );\n}\n';
